'use strict';
const subscriberView={routerId:'',status:'',severity:'',q:'',request:0};
function subscriberRouterOptions(routers){return '<option value="">All MikroTiks</option>'+routers.map(router=>`<option value="${router.id}" ${subscriberView.routerId===router.id?'selected':''}>${h(router.name)}</option>`).join('');}
function trafficValue(value){return Number.isFinite(value)?value.toFixed(value>=10?1:2)+' Mbps':'—';}
function subscriberMetrics(pppoe,events){return `<div class="dashboard-cards subscriber-cards"><div class="card metric-card"><div><div class="metric-title">Connected PPPoE</div><div class="metric-value">${pppoe.connected}</div><p>Current successful sessions</p></div></div><div class="card metric-card"><div><div class="metric-title">Disconnected</div><div class="metric-value">${pppoe.disconnected}</div><p>Previously observed sessions</p></div></div><div class="card metric-card"><div><div class="metric-title">Critical router events</div><div class="metric-value">${events.critical}</div><p>Last 30 days of reported logs</p></div></div><div class="card metric-card"><div><div class="metric-title">Warnings</div><div class="metric-value">${events.warning}</div><p>Authentication and system warnings</p></div></div></div>`;}
function subscriberStatus(value){return `<span class="status ${value==='Connected'?'online':value==='Disconnected'?'offline':'warning'}">${h(value)}</span>`;}
function paintSubscriberMonitoring(pppoe,events){
 $('#subscriber-metrics').innerHTML=subscriberMetrics(pppoe,events);
 $('#subscriber-router').innerHTML=subscriberRouterOptions(pppoe.routers);
 const sessions=pppoe.items.slice(0,250);$('#pppoe-count').textContent=`${pppoe.total} sessions · showing ${sessions.length}`;
 $('#pppoe-results').innerHTML=table(['CUSTOMER / USER','ROUTER','ADDRESS','STATUS','UPTIME','LIVE TRAFFIC','LAST OBSERVED'],sessions,item=>`<tr><td><strong>${h(item.customer||item.name)}</strong><small>${h(item.username)}${item.plan?' · '+h(item.plan):''}</small></td><td>${h(item.routerName)}</td><td>${h(item.ip||'—')}<small>${h(item.mac||'')}</small></td><td>${subscriberStatus(item.status)}</td><td>${h(item.uptime||'—')}</td><td><span class="traffic-pair">↓ ${trafficValue(item.traffic?.downloadMbps)}<br>↑ ${trafficValue(item.traffic?.uploadMbps)}</span></td><td>${h(stamp(item.lastObserved))}</td></tr>`,'No PPPoE sessions match these filters.');
 const logRows=events.items.slice(0,250);$('#router-event-count').textContent=`${events.total} events · showing ${logRows.length}`;
 $('#router-event-results').innerHTML=table(['SEVERITY','ROUTER','EVENT','MESSAGE','ROUTER TIME','RECEIVED'],logRows,item=>`<tr><td>${badge(item.severity)}</td><td>${h(item.routerName)}</td><td><strong>${h(item.title)}</strong><small>${h(item.topics)}</small></td><td class="event-message">${h(item.message)}</td><td>${h(item.occurredAt||'—')}</td><td>${h(stamp(item.observedAt))}</td></tr>`,'No warning or error events have been reported yet.');
 const missing=pppoe.routers.filter(router=>!router.configured||!router.fresh);$('#subscriber-reporting').innerHTML=missing.length?notice('Some routers need attention',missing.map(router=>`${h(router.name)}: ${!router.configured?'monitoring script not installed':'last report '+h(stamp(router.lastReport))}`).join(' · '),true):'';
}
async function loadSubscriberMonitoring(){const request=++subscriberView.request,params=new URLSearchParams({routerId:subscriberView.routerId,q:subscriberView.q,status:subscriberView.status}),eventParams=new URLSearchParams({routerId:subscriberView.routerId,q:subscriberView.q,severity:subscriberView.severity});try{const [pppoe,events]=await Promise.all([api('pppoe?'+params),api('router-events?'+eventParams)]);if(state.page!=='subscriber-monitoring'||request!==subscriberView.request)return;paintSubscriberMonitoring(pppoe,events);}catch(error){if(state.page==='subscriber-monitoring'&&request===subscriberView.request)$('#subscriber-content').innerHTML=notice('Could not load subscriber monitoring',h(error.message),true);}}
function renderSubscriberMonitoring(){
 $('#main').innerHTML=heading('PPPoE & router alerts','Monitor current subscriber sessions and warning/error events reported by your MikroTiks.','<button class="button secondary" id="refresh-subscriber-monitoring">Refresh</button>')+notice('Read-only monitoring','This page reads active PPPoE sessions and recent router warning/error logs. It does not disconnect users or change RouterOS.')+'<div id="subscriber-reporting"></div><div id="subscriber-content"><div id="subscriber-metrics" class="dashboard-cards subscriber-cards"><div class="card metric-card"><p>Loading live observations…</p></div></div><section class="card subscriber-panel"><div class="card-header"><div><h2>PPPoE sessions</h2><p>Connected subscribers, session duration and observed traffic rates.</p></div><span id="pppoe-count" class="muted"></span></div><div class="table-toolbar subscriber-toolbar"><input type="search" id="subscriber-query" aria-label="Search PPPoE sessions and router events" placeholder="Customer, username, IP, MAC or message"><select id="subscriber-router" aria-label="Filter by MikroTik"><option value="">All MikroTiks</option></select><select id="subscriber-status" aria-label="Filter PPPoE status"><option value="">All session states</option><option value="Connected">Connected</option><option value="Disconnected">Disconnected</option><option value="Report stale">Report stale</option></select></div><div id="pppoe-results" class="table-wrap"><div class="list-empty">Loading PPPoE sessions…</div></div></section><section class="card subscriber-panel"><div class="card-header"><div><h2>Router warning & error events</h2><p>Deduplicated logs collected by the read-only discovery agent.</p></div><span id="router-event-count" class="muted"></span></div><div class="table-toolbar subscriber-toolbar"><select id="subscriber-severity" aria-label="Filter router event severity"><option value="">All severities</option><option value="critical">Critical</option><option value="warning">Warning</option></select></div><div id="router-event-results" class="table-wrap"><div class="list-empty">Loading router events…</div></div></section></div>';
 $('#refresh-subscriber-monitoring').onclick=loadSubscriberMonitoring;let debounce;$('#subscriber-query').oninput=event=>{subscriberView.q=event.target.value;clearTimeout(debounce);debounce=setTimeout(loadSubscriberMonitoring,250);};$('#subscriber-router').onchange=event=>{subscriberView.routerId=event.target.value;loadSubscriberMonitoring();};$('#subscriber-status').onchange=event=>{subscriberView.status=event.target.value;loadSubscriberMonitoring();};$('#subscriber-severity').onchange=event=>{subscriberView.severity=event.target.value;loadSubscriberMonitoring();};loadSubscriberMonitoring();
}
setInterval(()=>{if(state.session?.user&&state.page==='subscriber-monitoring'&&!document.hidden&&!$('dialog[open]'))loadSubscriberMonitoring();},30000);
